#include <stdint.h>
#include "stm32f4xx.h"
#include "stm32f411xe.h"


void gpio_init(void);
void tim9_init(void);
void tim3_init(void);
void tim5_init(void);
void tim2_init(void);

int32_t arr_value = 100;
int32_t ccr_verde = 0; // CH1 -> PA6
int32_t ccr_azul  = 0; // CH2 -> PA7
int32_t ccr_rojo  = 0; // CH3 -> PC8
int32_t ccr_dac   = 0; // CH4 -> PC9


